<script setup lang="ts">import type {Metric} from './types';defineProps<{metrics:Metric[]}>();function main(x:Metric){if(x.state==='UNASSIGNED')return '未分配';if(x.state==='EMPTY')return x.key==='examAverage'?'暂无正式成绩':'暂无正式评价';return `${x.value}${x.unit||''}`}</script>
<template><div class="metric-grid"><div v-for="item in metrics" :key="item.key" class="metric"><span>{{item.label}}</span><strong>{{main(item)}}</strong><p v-if="item.denominator!==null">{{item.numerator}} / {{item.denominator}}</p><p v-else>{{item.note}}</p></div></div></template>
<style scoped>.metric-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}.metric{min-width:0;padding:14px;border:1px solid #e4e9f0;border-radius:6px;background:#fff}.metric span{color:#667085;font-size:13px}.metric strong{display:block;margin:7px 0 3px;color:#1769aa;font-size:23px;line-height:1.15}.metric p{margin:0;color:#8a94a6;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}@media(max-width:1100px){.metric-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:620px){.metric-grid{grid-template-columns:repeat(2,1fr)}}</style>
